<?php
declare(strict_types=1);
namespace App\Modules\Tenancy\Http\Controllers;
use App\Modules\Identity\Application\TenantStaffAuthorizationService; use App\Modules\Identity\Domain\TenantStaffContext; use App\Modules\Tenancy\Domain\AuthorizationDeniedException; use App\Modules\Tenancy\Domain\TenantAccessException; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
/** Read-only commercial timeline; deliberately separate from the security audit log. */
final class SalesActivityController {
 public function index(Request $r,TenantStaffAuthorizationService $authorization):JsonResponse{$actor=$this->context($r);if(!in_array(null,$authorization->effectiveGrants($actor)['activities.view']??[],true))throw new AuthorizationDeniedException;$input=$r->validate(['customer_id'=>['sometimes','nullable','uuid'],'deal_id'=>['sometimes','nullable','uuid'],'page'=>['sometimes','integer','min:1'],'per_page'=>['sometimes','integer','min:1','max:100']]);$q=DB::connection('pgsql_tenant_runtime')->table('sales_activities')->where('tenant_id',$actor->tenantId);if(isset($input['customer_id']))$q->where('customer_id',$input['customer_id']);if(isset($input['deal_id']))$q->where('deal_id',$input['deal_id']);$total=(clone $q)->count();$page=(int)($input['page']??1);$per=(int)($input['per_page']??25);return response()->json(['data'=>$q->orderByDesc('occurred_at')->forPage($page,$per)->get()->map(fn(object $row)=>['id'=>$row->id,'customer_id'=>$row->customer_id,'deal_id'=>$row->deal_id,'task_id'=>$row->task_id,'event_type'=>$row->event_type,'actor_present'=>$row->actor_membership_id !== null,'occurred_at'=>$row->occurred_at])->all(),'meta'=>['page'=>$page,'per_page'=>$per,'total'=>$total,'request_id'=>$r->attributes->get('request_id')]]);}
 private function context(Request $r):TenantStaffContext{$c=$r->attributes->get('tenant_staff_context');if(!$c instanceof TenantStaffContext)throw TenantAccessException::contextRequired();return $c;}
}
